@Component("warranty-handler")
@ProcessingGroup("warranty-processing-group")
public class WarrantyEventHandler {
	
	// core constructor
	WarrantyEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateWarrantyEvent
     */
    @EventHandler
    public void handle( CreateWarrantyEvent event) {
        entityManager.persist(new Warranty(event.getWarrantyId(), event.getCoverageMonths(), event.getAircraft(), event.getWarrantyType()));
    }

    /*
     * @param	event UpdateWarrantyEvent
     */
    @EventHandler
    public Warranty handle( UpdateWarrantyEvent event) {
    	entityManager.merge(new Warranty(event.getWarrantyId(), event.getCoverageMonths(), event.getAircraft(), event.getWarrantyType()));
    }
    
    /*
     * @param	event DeleteWarrantyEvent
     */
    @EventHandler
    public void on( DeleteWarrantyEvent event) {
    	Warranty entity = new Warranty();
   
    	// ------------------------------------------
    	// apply the WarrantyId
    	// ------------------------------------------
    	entity.setWarrantyId( event.getWarrantyId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final WarrantyRepository warrantyEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(WarrantyEventHandler.class.getName());

}
